-- 112: Original BrillaPrep 4PH1 beta questions, part 2.
-- Original practice content; not official Pearson questions.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_021', 'topic_edx_4ph1_5', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'A sample has mass 240 g and volume 80 cm³. Calculate its density.', 'multiple_choice', '["A. 3 g/cm³","B. 0.33 g/cm³","C. 160 g/cm³","D. 19,200 g/cm³"]', 'A', 'Density equals mass divided by volume: 240 ÷ 80 = 3 g/cm³. Therefore the correct answer is A: 3 g/cm³.', 'hard', 1, 1, 90, 'st_edx_4ph1_5', 'Calculate', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_022', 'topic_edx_4ph1_5', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'A force of 600 N acts on 0.20 m². Calculate the pressure.', 'multiple_choice', '["A. 120 Pa","B. 3,000 Pa","C. 600.2 Pa","D. 30,000 Pa"]', 'B', 'Pressure is force divided by area: 600 ÷ 0.20 = 3,000 pascals. Therefore the correct answer is B: 3,000 Pa.', 'easy', 2, 2, 90, 'st_edx_4ph1_5', 'Calculate', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_023', 'topic_edx_4ph1_5', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Why does gas pressure rise when a sealed gas is heated at constant volume?', 'multiple_choice', '["A. Particles lose all kinetic energy","B. The container volume becomes infinite","C. Particles move faster and collide more forcefully and often","D. Gas particles stop hitting walls"]', 'C', 'Heating raises average kinetic energy, increasing the rate of momentum transfer to container walls. Therefore the correct answer is C: Particles move faster and collide more forcefully and often.', 'medium', 1, 1, 90, 'st_edx_4ph1_5', 'Explain', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_024', 'topic_edx_4ph1_5', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'What happens during melting of a pure solid at constant pressure?', 'multiple_choice', '["A. Temperature rises without limit","B. Particles lose all energy","C. Mass becomes zero","D. Temperature stays constant while internal energy increases"]', 'D', 'Energy supplied weakens intermolecular bonds during the state change rather than raising temperature. Therefore the correct answer is D: Temperature stays constant while internal energy increases.', 'hard', 2, 2, 90, 'st_edx_4ph1_5', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_025', 'topic_edx_4ph1_5', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Why does liquid pressure increase with depth?', 'multiple_choice', '["A. More liquid above produces greater weight per unit area","B. Density becomes zero","C. Gravity acts upward","D. The surface pressure disappears"]', 'A', 'A deeper point supports a taller column of liquid, so the force per unit area is greater. Therefore the correct answer is A: More liquid above produces greater weight per unit area.', 'easy', 3, 3, 90, 'st_edx_4ph1_5', 'Explain', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_026', 'topic_edx_4ph1_6', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Which direction is the magnetic field outside a bar magnet?', 'multiple_choice', '["A. From south to north outside","B. From north pole to south pole","C. Clockwise around every magnet","D. There is no external field"]', 'B', 'By convention, external magnetic field lines leave north and enter south. Therefore the correct answer is B: From north pole to south pole.', 'medium', 2, 2, 90, 'st_edx_4ph1_6', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_027', 'topic_edx_4ph1_6', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'What increases the strength of an electromagnet?', 'multiple_choice', '["A. Removing the coil","B. Using no core and no current","C. Increasing current in its coil","D. Opening the circuit"]', 'C', 'A larger coil current produces a stronger magnetic field, especially with a soft-iron core. Therefore the correct answer is C: Increasing current in its coil.', 'hard', 1, 1, 90, 'st_edx_4ph1_6', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_028', 'topic_edx_4ph1_6', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'What causes a force on a current-carrying wire in a magnetic field?', 'multiple_choice', '["A. The wire loses all electrons","B. Gravity becomes stronger","C. The current becomes mass","D. Interaction between the wire’s field and the external field"]', 'D', 'The two magnetic fields interact, producing a force whose direction follows the motor rule. Therefore the correct answer is D: Interaction between the wire’s field and the external field.', 'easy', 2, 2, 90, 'st_edx_4ph1_6', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_029', 'topic_edx_4ph1_6', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'When is an emf induced in a coil?', 'multiple_choice', '["A. When magnetic flux through the coil changes","B. Whenever the coil is stationary in an unchanging field","C. Only when resistance is infinite","D. When no field is present"]', 'A', 'Electromagnetic induction requires a changing magnetic flux linkage through the circuit. Therefore the correct answer is A: When magnetic flux through the coil changes.', 'medium', 1, 1, 90, 'st_edx_4ph1_6', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_030', 'topic_edx_4ph1_6', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'An ideal transformer has 200 primary turns, 50 secondary turns and 240 V input. Calculate output voltage.', 'multiple_choice', '["A. 15 V","B. 60 V","C. 240 V","D. 960 V"]', 'B', 'Vs/Vp = Ns/Np, so Vs = 240 × 50/200 = 60 volts. Therefore the correct answer is B: 60 V.', 'hard', 3, 3, 90, 'st_edx_4ph1_6', 'Calculate', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_031', 'topic_edx_4ph1_7', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'What is the structure of an alpha particle?', 'multiple_choice', '["A. One electron","B. One proton only","C. Two protons and two neutrons","D. An electromagnetic wave"]', 'C', 'An alpha particle is a helium nucleus containing two protons and two neutrons. Therefore the correct answer is C: Two protons and two neutrons.', 'easy', 1, 1, 90, 'st_edx_4ph1_7', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_032', 'topic_edx_4ph1_7', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Which radiation is most penetrating?', 'multiple_choice', '["A. Alpha","B. Beta","C. Visible light from the source only","D. Gamma"]', 'D', 'Gamma radiation is highly penetrating and generally requires thick lead or concrete shielding. Therefore the correct answer is D: Gamma.', 'medium', 2, 2, 90, 'st_edx_4ph1_7', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_033', 'topic_edx_4ph1_7', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'What does half-life mean?', 'multiple_choice', '["A. Time for the number of undecayed nuclei or activity to halve","B. Time for every nucleus to decay","C. Time for mass to double","D. Time for temperature to halve"]', 'A', 'Radioactive decay is random, but a large sample shows a characteristic halving time. Therefore the correct answer is A: Time for the number of undecayed nuclei or activity to halve.', 'hard', 1, 1, 90, 'st_edx_4ph1_7', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_034', 'topic_edx_4ph1_7', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Why is background radiation subtracted from a source count?', 'multiple_choice', '["A. To increase random error","B. To estimate the count caused by the source alone","C. To stop the source decaying","D. To change the detector efficiency"]', 'B', 'The detector records environmental events as well as the source, so background must be accounted for. Therefore the correct answer is B: To estimate the count caused by the source alone.', 'easy', 2, 2, 90, 'st_edx_4ph1_7', 'Explain', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_035', 'topic_edx_4ph1_7', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'What change occurs in beta-minus decay?', 'multiple_choice', '["A. A proton becomes two neutrons","B. The nucleus emits four nucleons","C. A neutron changes to a proton and an electron is emitted","D. No nuclear change occurs"]', 'C', 'Beta-minus decay increases atomic number by one while leaving mass number unchanged. Therefore the correct answer is C: A neutron changes to a proton and an electron is emitted.', 'medium', 3, 3, 90, 'st_edx_4ph1_7', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_036', 'topic_edx_4ph1_8', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'What keeps a planet in approximately circular orbit around a star?', 'multiple_choice', '["A. No resultant force","B. Magnetic repulsion","C. Air resistance in space","D. Gravitational force providing centripetal acceleration"]', 'D', 'Gravity continuously changes the direction of velocity toward the star, producing orbital acceleration. Therefore the correct answer is D: Gravitational force providing centripetal acceleration.', 'hard', 2, 2, 90, 'st_edx_4ph1_8', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_037', 'topic_edx_4ph1_8', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'What is the main sequence stage of a star powered by?', 'multiple_choice', '["A. Fusion of hydrogen nuclei into helium","B. Chemical burning of coal","C. Fission of iron","D. Reflection of planet light only"]', 'A', 'Core hydrogen fusion releases energy and provides outward pressure balancing gravity. Therefore the correct answer is A: Fusion of hydrogen nuclei into helium.', 'easy', 1, 1, 90, 'st_edx_4ph1_8', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_038', 'topic_edx_4ph1_8', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'What does red-shift in distant galaxies indicate?', 'multiple_choice', '["A. They are all moving toward Earth","B. Their light wavelengths are stretched as they recede","C. Their temperatures are exactly equal","D. Light has stopped travelling"]', 'B', 'Systematic red-shift is evidence that distant galaxies are generally moving away as space expands. Therefore the correct answer is B: Their light wavelengths are stretched as they recede.', 'medium', 2, 2, 90, 'st_edx_4ph1_8', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_039', 'topic_edx_4ph1_8', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Which evidence supports the Big Bang model?', 'multiple_choice', '["A. Absence of all background radiation","B. A static unchanging Universe only","C. Cosmic microwave background radiation","D. Every galaxy being blue-shifted"]', 'C', 'The near-uniform microwave background is interpreted as cooled radiation from the early hot Universe. Therefore the correct answer is C: Cosmic microwave background radiation.', 'hard', 1, 1, 90, 'st_edx_4ph1_8', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_040', 'topic_edx_4ph1_8', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'What final remnant can a Sun-like star form?', 'multiple_choice', '["A. Black hole directly","B. Neutron star after every case","C. New planet only","D. White dwarf"]', 'D', 'After a red-giant phase and planetary nebula, the exposed core remains as a white dwarf. Therefore the correct answer is D: White dwarf.', 'easy', 3, 3, 90, 'st_edx_4ph1_8', 'Identify', 'AO1', 'board_edexcel');
